import {api,send} from './api.js';
import {renderReports} from './reports.js';
import {renderAssignmentWorkspace} from './assignments.js';
import {renderAdvisories} from './advisories.js';
import {isPunjabCoordinate, applyLocationSelection, reverseGeocode, geolocationFailureMessage} from './location.js';
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const PUNJAB_DISTRICTS=['Amritsar','Barnala','Bathinda','Faridkot','Fatehgarh Sahib','Fazilka','Ferozepur','Gurdaspur','Hoshiarpur','Jalandhar','Kapurthala','Ludhiana','Malerkotla','Mansa','Moga','Sri Muktsar Sahib','Pathankot','Patiala','Rupnagar','Sahibzada Ajit Singh Nagar','Sangrur','Shaheed Bhagat Singh Nagar','Tarn Taran'];
const roleLabels={ADMIN:'Administrator',GOV:'Government Official',NGO:'NGO Coordinator',GOV_VOL:'Government Volunteer',NGO_VOL:'NGO Volunteer',GOV_DRIVER:'Government Driver',NGO_DRIVER:'NGO Driver',CITIZEN:'Citizen'};
const moduleMap={ADMIN:['Dashboard Overview','Registration Approvals','User & Role Management','Emergency Oversight','Analytics & Reports','Support','Audit Logs','Settings'],GOV:['Command Center','Emergency Requests','Resource Allocation','Inventory & Warehouses','Volunteers','Shelters','Vehicles & Dispatch','Funds & Donations'],NGO:['NGO Command Center','Emergency Requests','Zone Operations','Volunteers','Vehicles & Dispatch','Inventory & Warehouses','Shelters & Relief Hubs','Funds & Donations','Reports & Support'],GOV_VOL:['My Assignments','Responder Tasks','My Profile','Availability','Notifications','Training & Safety'],NGO_VOL:['My Assignments','Volunteer Tasks','My Profile','Availability','Organization Updates','Notifications'],GOV_DRIVER:['My Dispatches','Vehicle & Route','Delivery History','My Profile','Availability','Notifications'],NGO_DRIVER:['My Dispatches','Vehicle & Route','Delivery History','My Profile','Availability','Notifications'],CITIZEN:['Overview','Report Emergency','My Emergency Requests','Find Shelters','Donations','Public Advisories','Notifications','Feedback & Support']};
const icons=['◈','⌁','▤','⌖','◉','♧','▱','◇','✓','▦','◌','◍','◎','≋'];
function toast(message){const t=$('#toast');if(!t)return;t.textContent=message;t.className='toast';t.style.display='block';setTimeout(()=>t.style.display='none',3500)}
function serial(form){const fd=new FormData(form),out={};for(const [key,value] of fd.entries())out[key]=Object.prototype.hasOwnProperty.call(out,key)?[...[].concat(out[key]),value]:value;for(const box of form.querySelectorAll('input[type=checkbox][name]'))out[box.name]=box.checked;return out}
function message(el,text,isError=true){if(el){el.textContent=text;el.style.color=isError?'var(--red)':'var(--green)'}}
async function authPages(){
 const login=$('#login-form'); if(login) login.addEventListener('submit',async e=>{e.preventDefault();const btn=$('button[type=submit]',login),err=$('#form-error');btn.disabled=true;btn.textContent='Signing in…';try{const res=await send('/api/login/',serial(login));location.href='/'+res.dashboard}catch(x){message(err,x.message)}finally{btn.disabled=false;btn.innerHTML='Sign in <span>→</span>'}});
 const reg=$('#register-form'); if(reg) reg.addEventListener('submit',async e=>{e.preventDefault();const d=serial(reg),err=$('#form-error');if(d.password!==d.confirm)return message(err,'Passwords do not match.');try{const res=await send('/api/register/',d);sessionStorage.setItem('registration-message',res.message+' Status: '+res.approval);location.href='/login.html'}catch(x){message(err,x.message)}});
 const roleSelect=$('#role');if(roleSelect){const update=()=>{const role=roleSelect.value;const org=$('.org-field');org.hidden=role==='CITIZEN';const orgInput=$('[name=organization]');orgInput.required=role!=='CITIZEN';$$('.extra-field').forEach(label=>{const active=label.dataset.for.split(',').includes(role);label.hidden=!active;const input=$('input',label);input.required=active&&label.dataset.for!=='GOV_VOL'})};roleSelect.addEventListener('change',update);update()}
 $$('[data-toggle]').forEach(b=>b.addEventListener('click',()=>{const input=b.parentElement.querySelector('input');input.type=input.type==='password'?'text':'password';b.setAttribute('aria-label',input.type==='password'?'Show password':'Hide password')}));
 const stored=sessionStorage.getItem('registration-message');if(stored&&$('#form-error')){message($('#form-error'),stored,false);sessionStorage.removeItem('registration-message')}
 const adv=$('#public-advisories'),sh=$('#public-shelters');if(adv||sh){try{const config=await api('/api/public-preferences/');const brand=$('#public-brand'),notice=$('#public-notice');if(brand&&config.preferences.platform_name)brand.textContent=config.preferences.platform_name;if(notice&&config.preferences.public_notice){notice.textContent=config.preferences.public_notice;notice.hidden=false}if(adv){const data=await api('/api/advisories/');adv.innerHTML=data.results.length?data.results.map(x=>`<article class="public-card"><small>${esc(x.severity||'MEDIUM')} · ${esc(x.location||'Public advisory')}</small><h3>${esc(x.title)}</h3><p>${esc(x.body)}</p></article>`).join(''):'<div class="public-card">No published advisories right now. Check back for updates.</div>'}if(sh){const d=await api('/api/shelters/');sh.innerHTML=d.results.length?d.results.map(x=>`<article class="public-card"><small>${esc(x.location)}</small><h3>${esc(x.name)}</h3><p>${x.available} spaces available · ${x.occupancy}/${x.capacity} occupied · ${esc(x.occupancy_band||x.status)}</p></article>`).join(''):'<div class="public-card">Shelter information is not available yet.</div>'}}catch{} }
}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function table(headers,rows=[]){return `<div class="table-wrap"><table class="records"><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${cell??''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
let state={section:'',data:null,map:null,me:null,modules:[]};
async function dashboard(){const shell=$('.shell');if(!shell)return;
 let me;try{me=await api('/api/me/')}catch{}if(!me?.authenticated){location.href='/login.html';return}
 state.me=me;const declared=shell.dataset.role||me.role;shell.dataset.role=me.role;const modules=moduleMap[me.role]||moduleMap.CITIZEN;state.modules=modules;
 const pageHeading=$('.topbar h1'),pageEyebrow=$('.topbar .eyebrow');if(pageEyebrow)pageEyebrow.textContent=me.role==='GOV'?'GOVERNMENT RESPONSE':me.role==='NGO'?'RELIEF ORGANIZATION':me.role==='CITIZEN'?'COMMUNITY RESPONSE':'FIELD OPERATIONS';if(pageHeading)pageHeading.textContent=me.role==='GOV'?'Government Relief Command Center':me.role==='NGO'?'NGO Relief Operations':me.role==='CITIZEN'?'Citizen Relief Workspace':`${roleLabels[me.role]||me.role} Workspace`;
 $('#hello').textContent=`Good day, ${me.name.split(' ')[0]}`;$('#account-info').textContent=`${roleLabels[me.role]||me.role}${me.organization?' · '+me.organization:''} · ${me.approval==='PENDING'?'Approval pending':'Connected response network'}`;
 const reportAction=$('#report-action');if(!['CITIZEN','GOV'].includes(me.role))reportAction.style.display='none';else reportAction.addEventListener('click',e=>{e.preventDefault();state.section='Report Emergency';renderSection();$('#section-content').scrollIntoView({behavior:'smooth',block:'start'})});
 $('#side-nav').innerHTML=modules.map((m,i)=>`<a href="#${encodeURIComponent(m)}" data-module="${esc(m)}" class="${i===0?'active':''}"><span class="nav-icon">${icons[i%icons.length]}</span>${esc(m)}</a>`).join('');
 $('#side-nav').addEventListener('click',e=>{const a=e.target.closest('[data-module]');if(!a)return;e.preventDefault();$$('#side-nav a').forEach(x=>x.classList.toggle('active',x===a));state.section=a.dataset.module;renderSection()});
 $('#logout').addEventListener('click',async()=>{await send('/api/logout/',{});location.href='/login.html'});
 $('#search').addEventListener('input',()=>renderSection());
 await refresh();state.section=modules[0];renderSection();
}
async function refresh(){try{state.data=await api('/api/dashboard/');renderMetrics();renderSide();if(state.map){state.map.remove();state.map=null}initMap()}catch(e){toast(e.message)}}
function renderMetrics(){const c=state.data.counts,role=state.me.role;let data;if(role==='ADMIN')data=[['Registered users',c.users,'All active platform accounts'],['Government officials',c.gov_officials,'Agency accounts'],['Registered NGOs',c.ngos,'Relief organizations'],['Pending approvals',c.pending_approvals,'Applications awaiting review'],['Open emergency requests',c.open_emergencies,'Shared response queue'],['Active response operations',c.active_operations,'Accepted or in progress'],['Current resource assignments',c.assignments,'Responders deployed'],['Recent activity',c.recent_activity,'Recorded in the last 24 hours']];else if(role==='GOV'||role==='NGO')data=[['High Priority Zones',c.high_priority_zones,'Critical or high-priority active locations'],['Affected Population',c.affected_population,'People reported across incidents'],['Relief Fulfillment',`${c.relief_fulfillment}%`,'Requests resolved'],['Allocated Fund','₹'+c.allocated_funds,'Recorded allocations']];else if(role==='GOV_DRIVER'||role==='NGO_DRIVER')data=[['My dispatches',c.my_dispatches,'Dispatch records assigned to you'],['Active tasks',c.my_assignments,'Assignments in progress'],['Open requests',c.open_emergencies,'Network response queue'],['Unread notifications',c.my_notifications,'Updates to review']];else if(role==='GOV_VOL'||role==='NGO_VOL')data=[['My active tasks',c.my_assignments,'Assignments in progress'],['Open requests',c.open_emergencies,'Network response queue'],['Unread notifications',c.my_notifications,'Updates to review'],['Available shelters',c.shelters,'Relief locations']];else data=[['My requests',state.data.emergencies.length,'Requests submitted by you'],['Open emergencies',c.open_emergencies,'Shared response queue'],['Available shelters',state.data.shelters.filter(s=>s.available>0).length,'Relief locations'],['My contributions','₹0','Your recorded contribution history']];$('#overview').innerHTML=data.map((x,i)=>`<article class="metric clickable" data-metric="${i}"><label>${x[0]}</label><strong>${x[1]}</strong><small>${x[2]}</small></article>`).join('');const targets={'Registered users':'User & Role Management','Government officials':'User & Role Management','Registered NGOs':'User & Role Management','Pending approvals':'Registration Approvals','Open emergency requests':'Emergency Oversight','Active response operations':'Emergency Oversight','Current resource assignments':'Resource Allocation','High Priority Zones':'Emergency Requests','Affected Population':'Emergency Requests','Relief Fulfillment':'Emergency Requests','Allocated Fund':'Relief Fund Utilization','My dispatches':'My Dispatches','My active tasks':'My Assignments','Unread notifications':'Notifications','Open emergencies':'My Emergency Requests','My requests':'My Emergency Requests','Available shelters':'Find Shelters'};$$('.metric').forEach(x=>x.addEventListener('click',()=>{const label=x.querySelector('label').textContent;const target=targets[label]||label;state.section=state.modules.includes(target)?target:state.modules[0];$$('#side-nav a').forEach(a=>a.classList.toggle('active',a.dataset.module===state.section));renderSection()}))}
function renderSide(){const c=state.data.counts;$('#side-content').innerHTML=`<div class="status-row"><span>Open requests</span><b>${c.open_emergencies}</b></div><div class="status-row"><span>Active operations</span><b>${c.active_operations}</b></div><div class="status-row"><span>Available shelter beds</span><b>${state.data.shelters.reduce((a,s)=>a+s.available,0)}</b></div><div class="status-row"><span>Network status</span><b style="color:var(--green)">Operational</b></div>`}
function initMap(){const el=$('#map');if(!el)return;if(!window.L){el.innerHTML='<div class="map-empty">Map library unavailable</div>';return}const host=el.parentElement;let controls=$('#shelter-map-controls');if(!controls){controls=document.createElement('form');controls.id='shelter-map-controls';controls.className='action-form';controls.innerHTML='<input name="query" placeholder="Search shelter, address, or organization"><select name="type"><option value="">All types</option>'+[...new Set(state.data.shelters.map(s=>s.type||'Shelter'))].sort().map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')+'</select><select name="status"><option value="">All statuses</option>'+[...new Set(state.data.shelters.map(s=>s.status))].sort().map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')+'</select><select name="availability"><option value="all">Any capacity</option><option value="available">Has available beds</option><option value="full">At capacity</option></select><button class="small-button">Find</button><small>Select a point inside Punjab to set the shelter coordinates.</small>';host.insertBefore(controls,el)}const typeSelect=controls.elements.namedItem('type'),statusSelect=controls.elements.namedItem('status'),selectedType=typeSelect.value,selectedStatus=statusSelect.value;typeSelect.innerHTML='<option value="">All types</option>'+[...new Set(state.data.shelters.map(s=>s.type||'Shelter'))].sort().map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');statusSelect.innerHTML='<option value="">All statuses</option>'+[...new Set(state.data.shelters.map(s=>s.status))].sort().map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');typeSelect.value=selectedType;statusSelect.value=selectedStatus;state.map=L.map(el,{scrollWheelZoom:false}).setView([30.8,75.8],7);const tiles=L.tileLayer('https://tile.openstreetmap.de/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a>',maxZoom:19,updateWhenIdle:true,keepBuffer:2}).addTo(state.map);let failedTiles=0;tiles.on('tileerror',()=>{failedTiles++;if(failedTiles>=3&&!el.querySelector('.map-tile-warning')){const warning=document.createElement('div');warning.className='map-tile-warning';warning.textContent='Map tiles are temporarily unavailable. Shelter records remain available in the list.';el.append(warning)}});tiles.on('tileload',()=>el.querySelector('.map-tile-warning')?.remove());const layer=L.layerGroup().addTo(state.map),render=()=>{layer.clearLayers();const fd=new FormData(controls),query=String(fd.get('query')||'').toLowerCase(),availability=fd.get('availability'),type=fd.get('type'),status=fd.get('status');const rows=state.data.shelters.filter(s=>(s.name+' '+s.location+' '+(s.type||'')+' '+(s.description||'')+' '+(s.organization||'')).toLowerCase().includes(query)&&(!type||s.type===type)&&(!status||s.status===status)&&(availability==='all'||(availability==='available'?s.available>0:s.available===0)));rows.forEach(s=>{const marker=L.marker([s.latitude,s.longitude]).addTo(layer);marker.bindPopup(`<b>${esc(s.name)}</b><br><b>${esc(s.type||'Shelter')}</b> · ${esc(s.status)}<br>${esc(s.location)}<br>${esc(s.description||'No additional details')}<br>Managed by ${esc(s.organization||'Community')}<br>${s.available} beds available · ${s.occupancy}/${s.capacity} occupied · ${esc(s.occupancy_band||s.status)}<br>Updated ${s.updated_at?new Date(s.updated_at).toLocaleString():'—'}`)});if(rows.length)state.map.fitBounds(L.latLngBounds(rows.map(s=>[s.latitude,s.longitude])).pad(.2));return rows};state.map.on('click',ev=>{const form=$('#shelter-form');if(!form)return;if(ev.latlng.lat<29.5||ev.latlng.lat>32.6||ev.latlng.lng<73.8||ev.latlng.lng>76.9){toast('Choose a map point inside Punjab');return}form.elements.namedItem('latitude').value=ev.latlng.lat.toFixed(6);form.elements.namedItem('longitude').value=ev.latlng.lng.toFixed(6);const pin=state.mapPin;if(pin)pin.remove();state.mapPin=L.marker(ev.latlng).addTo(state.map).bindPopup('New shelter location').openPopup()});controls.onsubmit=e=>{e.preventDefault();const rows=render();if(!rows.length)toast('No shelters match your search')};render()}
async function renderUsers(content,q){
 const filters=state.userFilters||{role:'',approval:'',organization:'',sort:'recent'};
 if(state.userQuery!==q){state.userQuery=q;state.userOffset=0}
 const offset=state.userOffset||0,params=new URLSearchParams({limit:'15',offset:String(offset),sort:filters.sort});
 if(q)params.set('q',q);for(const key of ['role','approval','organization'])if(filters[key])params.set(key,filters[key]);
 try{
  const [d,orgData]=await Promise.all([api(`/api/users/?${params}`),api('/api/agencies/')]);
  const roles=[['ADMIN','Administrator'],['GOV','Government Official'],['NGO','NGO Coordinator'],['GOV_VOL','Government Volunteer'],['NGO_VOL','NGO Volunteer'],['GOV_DRIVER','Government Driver'],['NGO_DRIVER','NGO Driver'],['CITIZEN','Citizen']];
  content.innerHTML=`<form id="user-filters" class="action-form"><label>Role <select name="role"><option value="">All roles</option>${roles.map(x=>`<option value="${x[0]}" ${filters.role===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></label><label>Approval <select name="approval"><option value="">All statuses</option>${['PENDING','APPROVED','REJECTED','SUSPENDED'].map(x=>`<option value="${x}" ${filters.approval===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Organization <input name="organization" value="${esc(filters.organization)}" placeholder="Search organization"></label><label>Sort <select name="sort">${[['recent','Newest first'],['oldest','Oldest first'],['name','Name'],['email','Email']].map(x=>`<option value="${x[0]}" ${filters.sort===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></label><button class="small-button">Apply</button><span>${d.pagination.total} accounts</span></form>`+(d.results.length?table(['Name','Email','Role','Organization','Approval','Joined','Account action'],d.results.map(x=>[esc(x.name),esc(x.email),`<select data-user-role="${x.id}" ${x.id===state.me.id?'disabled':''}>${roles.map(r=>`<option value="${r[0]}" ${x.role_code===r[0]?'selected':''}>${r[1]}</option>`).join('')}</select>`,`<select data-user-org="${x.id}" ${x.id===state.me.id?'disabled':''}><option value="">No organization</option>${orgData.results.map(o=>`<option value="${o.id}" ${String(x.organization_id)===String(o.id)?'selected':''}>${esc(o.name)} (${esc(o.kind_code)})</option>`).join('')}</select>`,`<span class="badge ${x.approval}">${esc(x.approval)}</span>${x.approval_history.length?`<details><summary>${x.approval_history.length} decision(s)</summary>${x.approval_history.map(h=>`<p><b>${esc(h.action)}</b><br><small>${new Date(h.created_at).toLocaleString()} · ${esc(h.actor)}</small>${h.reason?`<br>Reason: ${esc(h.reason)}`:""}</p>`).join("")}</details>`:"<small>No recorded decisions</small>"}`,new Date(x.joined).toLocaleDateString(),x.id===state.me.id?'Current account':`<button class="small-button" data-user-save="${x.id}">Save role</button> `+(x.approval==='SUSPENDED'?`<button class="small-button" data-user-status="${x.id}" data-status="APPROVED">Reactivate</button>`:`<button class="small-button" data-user-status="${x.id}" data-status="SUSPENDED">Suspend</button>`)])):'<div class="empty">No user accounts match these filters.</div>')+`<div class="action-form"><span>Showing ${d.pagination.total?offset+1:0}–${Math.min(offset+d.results.length,d.pagination.total)} of ${d.pagination.total}</span><button class="small-button" data-user-page="prev" ${d.pagination.previous_offset===null?'disabled':''}>Previous</button><button class="small-button" data-user-page="next" ${d.pagination.next_offset===null?'disabled':''}>Next</button></div>`;
  $('#user-filters').addEventListener('submit',e=>{e.preventDefault();filters.role=new FormData(e.currentTarget).get('role');filters.approval=new FormData(e.currentTarget).get('approval');filters.organization=new FormData(e.currentTarget).get('organization');filters.sort=new FormData(e.currentTarget).get('sort');state.userFilters=filters;state.userOffset=0;renderUsers(content,q)});
  content.onclick=async e=>{const page=e.target.closest('[data-user-page]');if(page){state.userOffset=page.dataset.userPage==='next'?d.pagination.next_offset:d.pagination.previous_offset;renderUsers(content,q);return}const save=e.target.closest('[data-user-save]');if(save){const row=save.closest('tr'),id=save.dataset.userSave,role=row.querySelector(`[data-user-role="${id}"]`).value,organization_id=row.querySelector(`[data-user-org="${id}"]`).value||null;try{await send(`/api/users/${id}/`,{role,organization_id});toast('User role and organization updated');renderUsers(content,q)}catch(x){toast(x.message)}return}const b=e.target.closest('[data-user-status]');if(!b)return;try{await send(`/api/users/${b.dataset.userStatus}/status/`,{status:b.dataset.status});toast('Account status updated');renderUsers(content,q)}catch(x){toast(x.message)}}
 }catch(e){content.innerHTML=`<div class="empty">${esc(e.message)}</div>`}
}
async function renderSupport(content){
 try{
  const data=await api('/api/tickets/'),isAdmin=state.me.role==='ADMIN';
  const ticketCards=data.results.map(t=>`<article class="public-card"><small>${esc(t.reference)} · ${esc(t.user)} · ${esc(t.role)} · ${esc(t.priority)} priority · ${esc(t.status)} · Updated ${new Date(t.updated_at).toLocaleString()}</small><h3>${esc(t.subject)}</h3><p>${esc(t.description)}</p><p><b>Assigned to:</b> ${esc(t.assigned_to||'Unassigned')}</p>${t.replies.map(r=>`<p><b>${esc(r.author)} · ${new Date(r.created_at).toLocaleString()}:</b> ${esc(r.body)}</p>`).join('')}<details><summary>Ticket history (${t.history.length})</summary>${t.history.map(h=>`<p><small>${esc(h.event_type)} · ${esc(h.actor)} · ${new Date(h.created_at).toLocaleString()}</small><br>${esc(h.detail.reply||h.detail.status||h.detail.subject||'Ticket updated')}</p>`).join('')}</details>${isAdmin?`<button class="small-button" data-assign-ticket="${t.id}">Assign to me</button>`:''}<form class="reply-form action-form" data-ticket="${t.id}"><input name="body" placeholder="Add a reply">${isAdmin?'<select name="status"><option value="">Keep status</option><option>Open</option><option>In Progress</option><option>Resolved</option></select><select name="priority"><option value="">Keep priority</option><option value="LOW">Low priority</option><option value="NORMAL">Normal priority</option><option value="HIGH">High priority</option><option value="URGENT">Urgent</option></select>':''}<button class="small-button">Reply / save</button></form></article>`).join('');
  content.innerHTML='<form id="ticket-form" class="action-form"><input name="subject" required placeholder="Subject"><input name="category" placeholder="Category"><select name="priority"><option value="NORMAL">Normal priority</option><option value="LOW">Low priority</option><option value="HIGH">High priority</option><option value="URGENT">Urgent</option></select><textarea name="description" required placeholder="How can we help?"></textarea><button class="small-button">Create ticket</button></form>'+(ticketCards||'<div class="empty">No support tickets yet.</div>');
  $('#ticket-form',content).addEventListener('submit',async event=>{event.preventDefault();try{const result=await send('/api/tickets/',serial(event.currentTarget));toast(`Ticket created · ${result.reference}`);renderSupport(content)}catch(error){toast(error.message)}});
  content.querySelectorAll('.reply-form').forEach(form=>form.addEventListener('submit',async event=>{event.preventDefault();try{await send(`/api/tickets/${form.dataset.ticket}/replies/`,serial(form));toast('Ticket updated');renderSupport(content)}catch(error){toast(error.message)}}));
  content.querySelectorAll('[data-assign-ticket]').forEach(button=>button.addEventListener('click',async()=>{try{await send(`/api/tickets/${button.dataset.assignTicket}/replies/`,{assigned_to:state.me.id});toast('Ticket assigned to you');renderSupport(content)}catch(error){toast(error.message)}}));
 }catch(error){content.innerHTML='<div class="empty">'+esc(error.message)+'</div>'}
}
