async function renderNgoAllocation(content,q){
 try{
  const [proposals,volunteers,drivers,vehicles,inventory]=await Promise.all([api('/api/allocations/'),api('/api/team/?kind=VOL'),api('/api/team/?kind=DRIVER'),api('/api/vehicles/'),api('/api/inventory/')]);
  const requests=state.data.emergencies.filter(e=>e.accepted_by===state.me.organization&&['ACCEPTED','IN_PROGRESS'].includes(e.status)&&(`${e.reference} ${e.location} ${e.description}`).toLowerCase().includes(q));
  const proposalCards=proposals.results.map(x=>{
   const title=x.kind==='VOL'?'Volunteer team proposal':x.kind==='DRIVER'?'Driver team proposal':'Relief supply proposal';
   const resources=x.kind==='STOCK'?`<b>Stock:</b> ${esc(x.inventory?.item||'Unavailable item')} · ${esc(x.inventory?.warehouse||'')}<br><b>Requested:</b> ${x.requested_quantity||0} ${esc(x.inventory?.unit||'units')} · <b>Available now:</b> ${x.inventory?.available_quantity??0}`:`<b>Responders:</b> ${x.users.map(u=>`${esc(u.name)} · ${esc(u.approval)} · ${esc(u.availability)}${u.active_assignment?' · already assigned':''}`).join(', ')}<br><b>Vehicles:</b> ${x.vehicles.map(v=>`${esc(v.registration)} · capacity ${v.capacity} · ${v.available?'available':'unavailable'}`).join(', ')||'Auto-select suitable available vehicles'}`;
   return `<article class="public-card"><small>${esc(x.emergency)} · ${esc(x.organization)} · ${esc(x.status)}</small><h3>${title} · ${esc(x.location)}</h3><p>${resources}</p><p>${esc(x.task_instructions||'No additional allocation notes')}${x.decision_note?`<br><b>Government decision:</b> ${esc(x.decision_note)}`:''}</p><details><summary>Decision history (${x.history.length})</summary>${x.history.map(h=>`<p>${esc(h.event_type)} · ${esc(h.actor)} · ${new Date(h.created_at).toLocaleString()}${h.detail.note?`<br>${esc(h.detail.note)}`:''}</p>`).join('')}</details>${x.status==='APPROVED'?`<button class="small-button" data-execute-allocation="${x.id}">Execute approved allocation</button>`:''}</article>`;
  }).join('');
  const cards=requests.map(e=>{
   const volunteerOptions=volunteers.results.filter(x=>x.approval==='APPROVED'&&x.availability==='AVAILABLE'&&!x.active).map(x=>`<label class="candidate-option"><input type="checkbox" name="user_ids" value="${x.id}"><span>${esc(x.name)} · ${esc(x.role)} · ${esc(x.skills||'Skills not listed')}</span></label>`).join('');
   const driverOptions=drivers.results.filter(x=>x.approval==='APPROVED'&&x.availability==='AVAILABLE'&&!x.active).map(x=>`<label class="candidate-option"><input type="checkbox" name="user_ids" value="${x.id}"><span>${esc(x.name)} · ${esc(x.role)}</span></label>`).join('');
   const vehicleOptions=vehicles.results.filter(x=>x.available&&x.capacity>=e.required_vehicle_capacity).map(x=>`<label class="candidate-option"><input type="checkbox" name="vehicle_ids" value="${x.id}"><span>${esc(x.registration)} · ${esc(x.kind)} · capacity ${x.capacity}</span></label>`).join('');
   const stockOptions=inventory.results.filter(x=>x.quantity>0).map(x=>`<option value="${x.id}">${esc(x.item)} · ${esc(x.warehouse)} · ${x.quantity} ${esc(x.unit)} available</option>`).join('');
   return `<article class="public-card"><small>${esc(e.reference)} · ${esc(e.status)}</small><h3>${esc(e.category)} · ${esc(e.location)}</h3><p>${esc(e.description)}<br><b>Required skills:</b> ${esc(e.required_skills.join(', ')||'None specified')} · <b>Minimum vehicle capacity:</b> ${e.required_vehicle_capacity}</p><form class="allocation-proposal-form action-form" data-emergency="${e.id}"><label>Resource type <select name="kind"><option value="VOL">Volunteer team</option><option value="DRIVER">Driver team</option></select></label><div class="proposal-volunteers">${volunteerOptions||'<p class="panel-copy">No available approved volunteers.</p>'}</div><div class="proposal-drivers" hidden>${driverOptions||'<p class="panel-copy">No available approved drivers.</p>'}</div><div class="proposal-vehicles" hidden>${vehicleOptions||'<p class="panel-copy">No suitable available vehicles.</p>'}</div><textarea name="task_instructions" placeholder="Proposed assignment instructions"></textarea><input name="pickup_location" placeholder="Driver pickup location"><textarea name="cargo_details" placeholder="Proposed cargo"></textarea><button class="small-button">Submit responder proposal for Government review</button></form><form class="stock-proposal-form action-form" data-emergency="${e.id}"><h4>Request emergency supplies</h4><select name="inventory_id" required>${stockOptions||'<option value="">No available stock</option>'}</select><input name="quantity" type="number" min="1" max="${Math.max(1,...inventory.results.map(x=>x.quantity))}" required placeholder="Quantity"><textarea name="note" placeholder="Why these supplies are needed"></textarea><button class="small-button" ${stockOptions?'':'disabled'}>Submit stock request for Government review</button></form></article>`;
  }).join('');
  content.innerHTML=`<h3>Government authorization proposals</h3>${proposalCards||'<div class="empty">No allocation proposals have been submitted.</div>'}<h3>Propose resources for an accepted request</h3>${cards||'<div class="empty">No accepted requests are available for resource proposals.</div>'}`;
  content.querySelectorAll('.allocation-proposal-form').forEach(form=>{
   const kind=form.elements.namedItem('kind'),vol=form.querySelector('.proposal-volunteers'),drv=form.querySelector('.proposal-drivers'),veh=form.querySelector('.proposal-vehicles');
   const updateMode=()=>{vol.hidden=kind.value!=='VOL';drv.hidden=kind.value!=='DRIVER';veh.hidden=kind.value!=='DRIVER';for(const panel of [vol,drv,veh])panel.querySelectorAll('input[type=checkbox]').forEach(box=>{box.disabled=panel.hidden;if(panel.hidden)box.checked=false})};
   kind.addEventListener('change',updateMode);updateMode();
   form.addEventListener('submit',async ev=>{ev.preventDefault();const fd=new FormData(form),user_ids=fd.getAll('user_ids'),vehicle_ids=fd.getAll('vehicle_ids');if(!user_ids.length)return toast('Select at least one responder');if(fd.get('kind')==='DRIVER'&&vehicle_ids.length!==user_ids.length)return toast('Select exactly one suitable vehicle per driver');try{await send('/api/allocations/',{emergency_id:Number(form.dataset.emergency),kind:fd.get('kind'),user_ids,vehicle_ids,task_instructions:fd.get('task_instructions'),pickup_location:fd.get('pickup_location'),cargo_details:fd.get('cargo_details')});toast('Proposal sent for Government authorization');renderNgoAllocation(content,q)}catch(x){toast(x.message)}});
  });
  content.querySelectorAll('.stock-proposal-form').forEach(form=>form.addEventListener('submit',async ev=>{ev.preventDefault();try{await send('/api/allocations/',{emergency_id:Number(form.dataset.emergency),kind:'STOCK',inventory_id:Number(form.elements.inventory_id.value),quantity:Number(form.elements.quantity.value),note:form.elements.note.value});toast('Stock request sent for Government authorization');renderNgoAllocation(content,q)}catch(x){toast(x.message)}}));
  content.onclick=async e=>{const button=e.target.closest('[data-execute-allocation]');if(!button)return;try{await send(`/api/allocations/${button.dataset.executeAllocation}/execute/`,{});toast('Approved allocation executed');await refresh();renderNgoAllocation(content,q)}catch(x){toast(x.message)}};
 }catch(e){content.innerHTML=`<div class="empty">${esc(e.message)}</div>`}
}
async function renderAllocationAuthorizations(content,q){
 try{
  const d=await api('/api/allocations/'),rows=d.results.filter(x=>!q||(`${x.emergency} ${x.location} ${x.organization} ${x.status} ${x.users.map(u=>u.name).join(' ')} ${x.vehicles.map(v=>v.registration).join(' ')} ${x.inventory?.item||''}`).toLowerCase().includes(q));
  const cards=rows.map(x=>{
   const title=x.kind==='VOL'?'Volunteer allocation':x.kind==='DRIVER'?'Driver allocation':'Emergency stock allocation';
   const resources=x.kind==='STOCK'?`<b>Item:</b> ${esc(x.inventory?.item||'No longer in inventory')} · ${esc(x.inventory?.warehouse||'')}<br><b>Requested:</b> ${x.requested_quantity||0} ${esc(x.inventory?.unit||'units')} · <b>Available:</b> ${x.inventory?.available_quantity??0} ${esc(x.inventory?.unit||'units')}`:`<b>Responders:</b> ${x.users.map(u=>`${esc(u.name)} · ${esc(u.approval)} · ${esc(u.availability)}${u.active_assignment?' · already assigned':''}`).join(', ')}<br><b>Vehicles:</b> ${x.vehicles.map(v=>`${esc(v.registration)} · capacity ${v.capacity} · ${v.available?'available':'unavailable'}`).join(', ')||'Auto-select suitable available vehicles'}`;
   return `<article class="public-card"><small>${esc(x.emergency)} · ${esc(x.emergency_status)} · ${esc(x.status)} · submitted ${new Date(x.created_at).toLocaleString()}</small><h3>${esc(x.organization)} · ${title}</h3><p><b>Requested by:</b> ${esc(x.requested_by)}<br><b>Area:</b> ${esc(x.location)}<br>${resources}</p><p><b>Instructions:</b> ${esc(x.task_instructions||'None')}<br><b>Pickup:</b> ${esc(x.pickup_location||'Not specified')}<br><b>Cargo:</b> ${esc(x.cargo_details||'Not specified')}</p><details><summary>Decision and submission history (${x.history.length})</summary>${x.history.map(h=>`<p>${esc(h.event_type)} · ${esc(h.actor)} · ${new Date(h.created_at).toLocaleString()}${h.detail.note?`<br>${esc(h.detail.note)}`:''}</p>`).join('')}</details>${x.status==='PENDING'?`<div class="action-form"><button class="small-button" data-review-allocation="${x.id}" data-decision="APPROVED">Approve proposal</button><button class="small-button" data-review-allocation="${x.id}" data-decision="REJECTED">Reject proposal</button></div>`:''}</article>`;
  }).join('');
  content.innerHTML='<div class="public-card"><b>Authorization limits</b><p>Responder proposals allow up to 20 team members; vehicle capacity and current stock availability are displayed. All resources are rechecked before execution.</p></div>'+(cards||'<div class="empty">No allocation proposals match this search.</div>');
  content.onclick=async e=>{const button=e.target.closest('[data-review-allocation]');if(!button)return;const decision=button.dataset.decision,response=prompt(decision==='REJECTED'?'Reason for rejecting this allocation:':'Authorization note (optional):');if(response===null)return;const note=response||'';if(decision==='REJECTED'&&!note.trim())return toast('A rejection reason is required');try{await send(`/api/allocations/${button.dataset.reviewAllocation}/review/`,{decision,note});toast(`Allocation proposal ${decision.toLowerCase()}`);renderAllocationAuthorizations(content,q)}catch(x){toast(x.message)}};
 }catch(e){content.innerHTML=`<div class="empty">${esc(e.message)}</div>`}
}
async function renderAllocation(content,q){if(state.me.role==='NGO'){renderNgoAllocation(content,q);return}try{const [team,drivers,vehicles,inventory]=await Promise.all([api('/api/team/?kind=VOL'),api('/api/team/?kind=DRIVER'),api('/api/vehicles/'),api('/api/inventory/')]);const requests=state.data.emergencies.filter(e=>['ACCEPTED','IN_PROGRESS'].includes(e.status)).filter(e=>(e.reference+e.location+e.description+e.required_skills.join(' ')).toLowerCase().includes(q));content.innerHTML=requests.length?requests.map(e=>`<article class="public-card allocation" data-request="${e.id}"><small>${esc(e.reference)} · ${esc(e.status)}</small><h3>${esc(e.category)} — ${esc(e.location)}</h3><p>${esc(e.accepted_by||'')} · ${esc(e.description)}</p><p><b>Requested skills:</b> ${esc(e.required_skills.join(', ')||'None specified')} · <b>Transport:</b> ${e.needs_transport?`Yes, capacity ≥ ${e.required_vehicle_capacity}`:'Not specified'}</p><form class="assign-form action-form" data-request="${e.id}"><label>Assignment type <select name="kind"><option value="VOL">Volunteers</option><option value="DRIVER">Drivers and vehicles</option></select></label><div class="candidate-list"></div><textarea name="task_instructions" placeholder="Instructions for selected responders"></textarea><div class="driver-details" hidden><input name="pickup_location" placeholder="Pickup location"><input name="cargo_details" placeholder="Cargo or relief supplies"><p><b>Choose one suitable vehicle per selected driver</b></p><div class="vehicle-list"></div></div><button class="small-button">Assign selected responders</button></form><form class="supply-allocation-form action-form" data-request="${e.id}"><h4>Allocate relief supplies</h4><select name="inventory_id" required>${inventory.results.filter(i=>i.quantity>0).map(i=>`<option value="${i.id}">${esc(i.item)} · ${esc(i.category)} · ${esc(i.warehouse)} · ${i.quantity} ${esc(i.unit)}</option>`).join('')}</select><input name="quantity" type="number" min="1" required placeholder="Quantity"><input name="note" placeholder="Allocation note"><button class="small-button" ${inventory.results.some(i=>i.quantity>0)?'':'disabled'}>Issue supplies to this request</button></form></article>`).join(''):'<div class="empty">No accepted requests need allocation.</div>';content.querySelectorAll('.assign-form').forEach(form=>{const kind=form.querySelector('[name=kind]'),list=form.querySelector('.candidate-list'),driverDetails=form.querySelector('.driver-details'),vehicleList=form.querySelector('.vehicle-list'),request=requests.find(x=>String(x.id)===form.dataset.request);const renderCandidates=()=>{const rows=kind.value==='VOL'?team.results:drivers.results;driverDetails.hidden=kind.value!=='DRIVER';const eligibleVehicles=vehicles.results.filter(v=>v.available&&v.capacity>=request.required_vehicle_capacity);vehicleList.innerHTML=kind.value==='DRIVER'?(eligibleVehicles.length?eligibleVehicles.map(v=>`<label class="candidate-option"><input type="checkbox" name="vehicle_ids" value="${v.id}"><span><b>${esc(v.registration)}</b> · ${esc(v.kind)} · capacity ${v.capacity} · ${esc(v.organization)}</span></label>`).join(''):'<p class="panel-copy">No available vehicle meets the requested capacity.</p>'):'';const eligible=rows.filter(x=>x.availability==='AVAILABLE'&&!x.active&&x.approval==='APPROVED'&&(kind.value==='VOL'||vehicles.results.some(v=>v.available&&v.capacity>=request.required_vehicle_capacity)));list.innerHTML=eligible.length?eligible.map(x=>{const skills=Array.isArray(x.skills)?x.skills.join(', '):x.skills;const matches=request.required_skills.some(s=>String(skills).toLowerCase().includes(s.toLowerCase()));return `<label class="candidate-option"><input type="checkbox" name="user_ids" value="${x.id}"><span><b>${esc(x.name)}</b> · ${esc(x.role)}<br><small>${esc(x.organization||'No organization')} · ${esc(x.approval)} · ${esc(x.availability)}${skills?` · Skills: ${esc(skills)}`:''}${kind.value==='VOL'&&request.required_skills.length?` · ${matches?'Matches required skill':'Check skill fit'}`:''}${kind.value==='DRIVER'?` · Eligible vehicles: ${vehicles.results.filter(v=>v.available&&v.capacity>=request.required_vehicle_capacity).map(v=>`${esc(v.registration)} (${v.kind}, cap. ${v.capacity})`).join(', ')||'None available'}`:''}</small></span></label>`}).join(''):'<p class="panel-copy">No approved, available responders match this organization right now.</p>'};kind.addEventListener('change',renderCandidates);renderCandidates();form.addEventListener('submit',async ev=>{ev.preventDefault();const fd=new FormData(form),user_ids=fd.getAll('user_ids'),vehicle_ids=fd.getAll('vehicle_ids');if(!user_ids.length)return toast('Select at least one responder');if(kind.value==='DRIVER'&&vehicle_ids.length!==user_ids.length)return toast('Select exactly one vehicle per selected driver');try{await send(`/api/emergencies/${form.dataset.request}/assign/`,{kind:fd.get('kind'),user_ids,vehicle_ids,task_instructions:fd.get('task_instructions'),pickup_location:fd.get('pickup_location'),cargo_details:fd.get('cargo_details')});toast('Responders assigned');await refresh();renderSection()}catch(e){toast(e.message)}})});content.querySelectorAll('.supply-allocation-form').forEach(form=>form.addEventListener('submit',async ev=>{ev.preventDefault();const fd=new FormData(form),item=inventory.results.find(i=>String(i.id)===fd.get('inventory_id'));if(!item)return toast('Select an inventory item');try{await send('/api/inventory/',{kind:'ISSUE',warehouse:item.warehouse,item:item.item,category:item.category,unit:item.unit,quantity:fd.get('quantity'),minimum_quantity:item.minimum_quantity,emergency_id:form.dataset.request,note:fd.get('note')});toast('Supplies allocated to the emergency');await refresh();renderSection()}catch(e){toast(e.message)}}))}catch(e){content.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function shelterTable(rows,canManage=false){return table(['Shelter','Type / details','Address','Contact','Capacity','Available','Status','Last updated',...(canManage?['Manage']:[])],rows.map(s=>[esc(s.name),`<b>${esc(s.type||'Shelter')}</b><br><small>${esc(s.description||'—')}</small>`,esc(s.location),s.contact_phone?`<a href="tel:${esc(s.contact_phone)}">${esc(s.contact_phone)}</a>`:'—',s.capacity,`<b>${s.available}</b> / ${s.capacity}`,`<span class="badge ${s.status}">${esc(s.status)}</span><br><small>${esc(s.occupancy_band||'')}</small>`,s.updated_at?new Date(s.updated_at).toLocaleString():'—',...(canManage&&((state.me.role==='ADMIN')||s.organization===state.me.organization)?[`<button class="small-button" data-shelter-history="${s.id}">History</button> <button class="small-button" data-edit-shelter="${s.id}">Edit</button><br><input data-occupancy="${s.id}" type="number" min="0" max="${s.capacity}" value="${s.occupancy}" style="width:70px"><button class="small-button" data-update-shelter="${s.id}">Save occupancy</button>`]:canManage?['—']:[]) ]))}
async function renderDonations(content){try{const [campaignData,donationData]=await Promise.all([api('/api/campaigns/'),api('/api/donations/')]);const isDemo=campaignData.demo_mode;content.innerHTML=`<div class="public-card"><b>${isDemo?'DEMONSTRATION MODE':'PLEDGE MODE'}</b><p>${isDemo?'Entries are written to an in-app ledger. No money is transferred.':'No payment provider is connected. Submissions remain pending; no payment is charged.'}</p></div><h3>Available relief campaigns</h3>${campaignData.results.length?`<div class="card-grid">${campaignData.results.map(c=>`<article class="public-card"><small>${esc(c.organization||'Relief campaign')} · CAMPAIGN</small><h3>${esc(c.name)}</h3><p><b>Recipient:</b> ${esc(c.recipient)}</p><p>${esc(c.description)}</p><p><b>Goal:</b> ${esc(c.currency)} ${esc(c.goal_amount)} · <b>Provider-verified payments:</b> ${esc(c.currency)} ${esc(c.confirmed_total)}</p>${c.demo_confirmed_total!=='0.00'?`<p><b>Recorded Contributions:</b> ${esc(c.currency)} ${(Number(c.demo_confirmed_total||0)+Number(c.confirmed_total||0)).toFixed(2)}</p>`:''}<form class="campaign-donation-form action-form" data-campaign="${c.id}" data-campaign-name="${esc(c.name)}"><input type="hidden" name="campaign_id" value="${c.id}"><input name="amount" type="number" min="1" step="0.01" required placeholder="Amount (${esc(c.currency)})"><button class="small-button">Record contribution</button></form></article>`).join('')}</div>`:'<div class="empty">No published donation campaigns are available.</div>'}<h3>My donation history</h3>${donationData.results.length?table(['Reference','Campaign / recipient','Amount','Workflow status','Record type','Date','Record details'],donationData.results.map(d=>[esc(d.reference),`${esc(d.campaign||'Relief')}<br><small>${esc(d.recipient||'')}</small>`,`${esc(d.currency)} ${esc(d.amount)}`,`<span class="badge ${d.status}">${esc(d.status_label||d.status)}</span>`,d.demo?'<span class="badge">In-app ledger</span>':'Submission record',new Date(d.created_at).toLocaleDateString(),d.receipt_url?`<a href="${d.receipt_url}">Provider-verified record</a>`:`<details><summary>View record</summary><small>${esc(d.status_label||'Status recorded')} · no payment receipt is available.</small></details>`])):'<div class="empty">No donations or pledges yet.</div>'}`;content.querySelectorAll('.campaign-donation-form').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const d=serial(form);const amount=Number(d.amount);if(!confirm(`Review ${d.currency||'INR'} ${amount.toFixed(2)} for ${form.dataset.campaignName}. ${isDemo?'This is a demo and will not transfer money.':'No payment will be charged.'} Continue?`))return;try{const result=await send('/api/donations/',d);toast(result.message);await renderDonations(content)}catch(x){toast(x.message)}}));content.querySelectorAll('[data-demo-donation]').forEach(button=>button.addEventListener('click',async()=>{try{const result=await send(`/api/donations/${button.dataset.demoDonation}/demo-result/`,{status:button.dataset.result});toast(result.message);await refresh();await renderDonations(content)}catch(x){toast(x.message)}}))}catch(e){content.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
