async function renderCitizenDonations(content){
 try{
  const [campaignData,donationData]=await Promise.all([api('/api/campaigns/'),api('/api/donations/')]);
  const campaigns=campaignData.results.filter(c=>['GOV','NGO'].includes(c.organization_kind));
  const organizations=campaignData.organizations?.length?campaignData.organizations:[...new Map(campaigns.map(c=>[c.organization_id,{id:c.organization_id,name:c.organization,kind:c.organization_kind}])).values()];
  const orgOptions=kind=>organizations.filter(o=>o.kind===kind).map(o=>`<option value="${o.id}">${esc(o.name)}</option>`).join('');
  const campaignOptions=(kind,orgId)=>campaigns.filter(c=>c.organization_kind===kind&&c.organization_id===Number(orgId)).map(c=>`<option value="${c.id}">${esc(c.name)} · ${esc(c.recipient)}</option>`).join('');
  const initial=organizations.find(o=>o.kind==='GOV')||organizations[0];
  const amountTotal=Number(donationData.summary?.recorded_total??donationData.results.filter(row=>(row.demo&&row.status==='DEMO_RECORDED')||(!row.demo&&row.status==='PAYMENT_VERIFIED'&&row.provider_reference)).reduce((sum,row)=>sum+Number(row.amount||0),0));
  const pendingTotal=Number(donationData.summary?.pending_total??donationData.results.filter(row=>row.status==='SUBMITTED').reduce((sum,row)=>sum+Number(row.amount||0),0));
  const campaignTable=campaigns.map(c=>[esc(c.organization),esc(c.name),`INR ${esc(c.goal_amount)}`,`INR ${(Number(c.confirmed_total||0)+Number(c.demo_confirmed_total||0)).toFixed(2)}`]);
  const history=donationData.results.map(row=>{
   const events=row.history?.length?`<details><summary>View record</summary><p><b>Reference:</b> ${esc(row.display_reference||row.reference)}<br><b>Record type:</b> ${row.demo?'In-app contribution ledger':'Organization submission'}<br><b>Status history:</b></p><ul>${row.history.map(event=>`<li>${esc(event.to_status.replaceAll('_',' ').toLowerCase())} · ${new Date(event.created_at).toLocaleString()}${event.to_status==='REJECTED'&&event.note?`<br><small>Review note: ${esc(event.note)}</small>`:''}</li>`).join('')}</ul>${row.receipt_url?`<a href="${esc(row.receipt_url)}">Provider-verified payment receipt</a>`:'<small>This record is not a payment receipt.</small>'}</details>`:'<details><summary>View record</summary><p>This contribution record is saved to your account. No external payment is represented.</p></details>';
   const status=row.status==='DEMO_RECORDED'?'Recorded':row.status_label||row.status.replaceAll('_',' ');
   return [esc(row.display_reference||row.reference),esc(row.organization||row.recipient||'—'),esc(row.campaign||'—'),`INR ${esc(row.amount)}`,`<span class="badge ${esc(row.status)}">${esc(status)}</span>`,new Date(row.created_at).toLocaleString(),events];
  });
  content.innerHTML=`<h3>Contributions</h3><article class="public-card contribution-note"><b>Contribution records</b><p>Entries are saved to your account and reviewed by the selected organization. DRRAS has no connected payment gateway, so these records do not mean money was transferred or received.</p></article><form id="citizen-demo-transfer" class="action-form contribution-form"><label>Recipient type<select name="organization_kind"><option value="GOV">Government</option><option value="NGO">NGO</option></select></label><label>Organization<select name="organization_id" required>${orgOptions(initial?.kind||'GOV')}</select></label><label>Campaign<select name="campaign_id" required>${campaignOptions(initial?.kind||'GOV',initial?.id||'')}</select></label><label>Amount (INR)<input name="amount" type="number" min="0.01" max="9999999999.99" step="0.01" required></label><button class="small-button">Review Contribution</button></form><section class="public-card contribution-summary"><h3>Recipient Contribution Summary</h3><p class="panel-copy">Recorded Contributions include in-app demonstration-ledger entries and any payment independently verified by a provider.</p>${campaignTable.length?table(['Organization','Campaign','Goal','Recorded Contributions'],campaignTable):'<div class="empty">No published campaigns are available.</div>'}<p><small>My recorded contribution entries: <b>INR ${amountTotal.toFixed(2)}</b> · Pending review: <b>INR ${pendingTotal.toFixed(2)}</b></small></p></section><section class="contribution-history"><h3>My Contribution History</h3>${history.length?table(['Reference','Recipient organization','Campaign','Amount','Status','Submitted','Record details'],history):'<div class="empty">No contribution records are associated with your account.</div>'}</section>`;
  const form=content.querySelector('#citizen-demo-transfer'),kind=form.elements.organization_kind,org=form.elements.organization_id,campaign=form.elements.campaign_id;
  kind.addEventListener('change',()=>{org.innerHTML=orgOptions(kind.value);campaign.innerHTML=campaignOptions(kind.value,org.value)});
  org.addEventListener('change',()=>{campaign.innerHTML=campaignOptions(kind.value,org.value)});
  form.addEventListener('submit',async event=>{event.preventDefault();const amount=Number(form.elements.amount.value),recipient=org.options[org.selectedIndex]?.textContent||'selected organization';if(!campaign.value)return toast('No published campaign exists for the selected organization.');if(!confirm(`Review INR ${amount.toFixed(2)} for ${recipient} through ${campaign.options[campaign.selectedIndex].textContent}. This creates an in-app contribution ledger entry only; no payment is processed. Continue?`))return;try{const result=await send('/api/demo-transfers/',{organization_kind:kind.value,organization_id:Number(org.value),campaign_id:Number(campaign.value),amount:form.elements.amount.value});toast(result.message);await refresh();renderCitizenDonations(content)}catch(error){toast(error.message)}});
 }catch(error){content.innerHTML=`<div class="empty">${esc(error.message)}</div>`}
}
